SELECT c.schedule_id, c.schedule_name, c.cluster_name, c.frequency_description, c.expected_frequency_minutes, c.expected_freshness_sla, c.freshness_sla_minutes, c."priority", c.owner_contact, c.failure_action, c.monitoring_required, le.run_id AS last_run_id, CASE WHEN (COALESCE(lss.failed_step_count, (0)::bigint) > 0) THEN 'FAILED'::character varying WHEN (COALESCE(es.expected_step_count, (0)::bigint) = 0) THEN 'INCOMPLETE'::character varying WHEN (COALESCE(lss.logged_step_count, (0)::bigint) < es.expected_step_count) THEN 'INCOMPLETE'::character varying WHEN (date_diff(('minute'::character varying)::text, lss.earliest_step_started_at, lss.latest_step_started_at) > c.expected_frequency_minutes) THEN 'INCOMPLETE'::character varying WHEN (lss.successful_step_count = es.expected_step_count) THEN 'SUCCESS'::character varying ELSE 'INCOMPLETE'::character varying END AS last_run_status, lss.run_started_at AS last_run_started_at, lss.run_completed_at AS last_run_completed_at, ls.last_success_at, lf.last_failed_at, es.expected_step_count, COALESCE(lss.successful_step_count, (0)::bigint) AS successful_step_count, COALESCE(lss.failed_step_count, (0)::bigint) AS failed_step_count, lf.failed_step, lf.error_message, date_diff(('minute'::character varying)::text, ls.last_success_at, getdate()) AS minutes_since_last_success, CASE WHEN (COALESCE(lss.failed_step_count, (0)::bigint) > 0) THEN 'FAILED'::character varying WHEN (COALESCE(es.expected_step_count, (0)::bigint) = 0) THEN 'INCOMPLETE'::character varying WHEN (ls.last_success_at IS NULL) THEN 'INCOMPLETE'::character varying WHEN (COALESCE(lss.logged_step_count, (0)::bigint) < es.expected_step_count) THEN 'INCOMPLETE'::character varying WHEN (date_diff(('minute'::character varying)::text, lss.earliest_step_started_at, lss.latest_step_started_at) > c.expected_frequency_minutes) THEN 'INCOMPLETE'::character varying WHEN (lss.successful_step_count <> es.expected_step_count) THEN 'INCOMPLETE'::character varying WHEN (date_diff(('minute'::character varying)::text, ls.last_success_at, getdate()) > c.freshness_sla_minutes) THEN 'STALE'::character varying ELSE 'CURRENT'::character varying END AS refresh_status, getdate() AS refreshed_at FROM (((((dba_monitoring.redshift_scheduled_query_config c LEFT JOIN (SELECT enabled_steps.schedule_id, count(*) AS expected_step_count FROM (SELECT DISTINCT redshift_scheduled_query_steps.schedule_id, redshift_scheduled_query_steps.step_order FROM dba_monitoring.redshift_scheduled_query_steps WHERE (redshift_scheduled_query_steps.enabled = true)) enabled_steps GROUP BY enabled_steps.schedule_id) es ON ((es.schedule_id = c.schedule_id))) LEFT JOIN (SELECT ranked_steps.schedule_id, count(*) AS logged_step_count, sum(CASE WHEN ((ranked_steps.status)::text = ('SUCCESS'::character varying)::text) THEN 1 ELSE 0 END) AS successful_step_count, sum(CASE WHEN ((ranked_steps.status)::text = ('FAILED'::character varying)::text) THEN 1 ELSE 0 END) AS failed_step_count, min(ranked_steps.start_time) AS run_started_at, "max"(ranked_steps.end_time) AS run_completed_at, min(ranked_steps.start_time) AS earliest_step_started_at, "max"(ranked_steps.start_time) AS latest_step_started_at FROM (SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, h.parsed_step_order, pg_catalog.row_number() OVER(  PARTITION BY h.schedule_id, h.parsed_step_order ORDER BY h.start_time DESC, h.execution_id DESC) AS rn FROM (SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, h.parsed_step_order FROM ((SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, ("replace"(split_part((h.run_id)::text, ('-'::character varying)::text, 2), ('STEP'::character varying)::text, (''::character varying)::text))::integer AS parsed_step_order FROM dba_monitoring.v_redshift_scheduled_query_history h WHERE ((h.run_id)::text ~~ ('S%-STEP%'::character varying)::text)) h JOIN (SELECT DISTINCT redshift_scheduled_query_steps.schedule_id, redshift_scheduled_query_steps.step_order FROM dba_monitoring.redshift_scheduled_query_steps WHERE (redshift_scheduled_query_steps.enabled = true)) s ON (((s.schedule_id = h.schedule_id) AND (s.step_order = h.parsed_step_order))))) h) ranked_steps WHERE (ranked_steps.rn = 1) GROUP BY ranked_steps.schedule_id) lss ON ((lss.schedule_id = c.schedule_id))) LEFT JOIN (SELECT configured_history.schedule_id, configured_history.run_id, pg_catalog.row_number() OVER(  PARTITION BY configured_history.schedule_id ORDER BY configured_history.start_time DESC, configured_history.execution_id DESC) AS rn FROM (SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, h.parsed_step_order FROM ((SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, ("replace"(split_part((h.run_id)::text, ('-'::character varying)::text, 2), ('STEP'::character varying)::text, (''::character varying)::text))::integer AS parsed_step_order FROM dba_monitoring.v_redshift_scheduled_query_history h WHERE ((h.run_id)::text ~~ ('S%-STEP%'::character varying)::text)) h JOIN (SELECT DISTINCT redshift_scheduled_query_steps.schedule_id, redshift_scheduled_query_steps.step_order FROM dba_monitoring.redshift_scheduled_query_steps WHERE (redshift_scheduled_query_steps.enabled = true)) s ON (((s.schedule_id = h.schedule_id) AND (s.step_order = h.parsed_step_order))))) configured_history) le ON (((le.schedule_id = c.schedule_id) AND (le.rn = 1)))) LEFT JOIN (SELECT s.schedule_id, CASE WHEN (count(ss.last_step_success_at) = count(*)) THEN min(ss.last_step_success_at) ELSE NULL::timestamp without time zone END AS last_success_at FROM ((SELECT DISTINCT redshift_scheduled_query_steps.schedule_id, redshift_scheduled_query_steps.step_order FROM dba_monitoring.redshift_scheduled_query_steps WHERE (redshift_scheduled_query_steps.enabled = true)) s LEFT JOIN (SELECT configured_history.schedule_id, configured_history.parsed_step_order, "max"(configured_history.end_time) AS last_step_success_at FROM (SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, h.parsed_step_order FROM ((SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, ("replace"(split_part((h.run_id)::text, ('-'::character varying)::text, 2), ('STEP'::character varying)::text, (''::character varying)::text))::integer AS parsed_step_order FROM dba_monitoring.v_redshift_scheduled_query_history h WHERE ((h.run_id)::text ~~ ('S%-STEP%'::character varying)::text)) h JOIN (SELECT DISTINCT redshift_scheduled_query_steps.schedule_id, redshift_scheduled_query_steps.step_order FROM dba_monitoring.redshift_scheduled_query_steps WHERE (redshift_scheduled_query_steps.enabled = true)) s ON (((s.schedule_id = h.schedule_id) AND (s.step_order = h.parsed_step_order))))) configured_history WHERE ((configured_history.status)::text = ('SUCCESS'::character varying)::text) GROUP BY configured_history.schedule_id, configured_history.parsed_step_order) ss ON (((ss.schedule_id = s.schedule_id) AND (ss.parsed_step_order = s.step_order)))) GROUP BY s.schedule_id) ls ON ((ls.schedule_id = c.schedule_id))) LEFT JOIN (SELECT configured_history.schedule_id, configured_history.end_time AS last_failed_at, configured_history.failed_step, configured_history.error_message, pg_catalog.row_number() OVER(  PARTITION BY configured_history.schedule_id ORDER BY configured_history.end_time DESC, configured_history.start_time DESC, configured_history.execution_id DESC) AS rn FROM (SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, h.parsed_step_order FROM ((SELECT h.execution_id, h.schedule_id, h.schedule_name, h.query_id, h.status, h.start_time, h.end_time, h.duration_seconds, h.rows_processed, h.refresh_timestamp, h.error_message, h.collected_at, h.current_step, h.failed_step, h.completed_steps, h.current_step_order, h.failed_step_order, h.run_id, ("replace"(split_part((h.run_id)::text, ('-'::character varying)::text, 2), ('STEP'::character varying)::text, (''::character varying)::text))::integer AS parsed_step_order FROM dba_monitoring.v_redshift_scheduled_query_history h WHERE ((h.run_id)::text ~~ ('S%-STEP%'::character varying)::text)) h JOIN (SELECT DISTINCT redshift_scheduled_query_steps.schedule_id